from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(group):
        balance = 0
        for char in group:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    result = []
    left_index = 0

    while left_index < len(paren_string):
        if '(' in paren_string[left_index:]:
            left_paren_index = paren_string.index('(', left_index)

            if not is_balanced(paren_string[left_paren_index:left_index+10]):
                return []

            while left_paren_index + 10 <= len(paren_string) and is_balanced(paren_string[left_paren_index:left_paren_index+10]):
                left_paren_index += 10

            next_open_index = paren_string[left_paren_index:].index('(')
            right_paren_index = paren_string[left_paren_index + next_open_index:].index(')')

            group = paren_string[left_paren_index:right_paren_index + 1]
            result.append(group)

            left_index = right_paren_index + 1
        else:
            left_index += 1

    return result
