def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.

    Examples:
    >>> max_value_on_paths(2, [(1, 2, 1), (2, 1, 2), (0, 0, 0)])
    3
    >>> max_value_on_paths(8, [
    ...     (2, 3, 13), (2, 6, 6), (3, 5, 7), (4, 4, 14),
    ...     (5, 2, 21), (5, 6, 4), (6, 3, 15), (7, 2, 14),
    ...     (0, 0, 0)])
    67
    """
    if N <= 0:
        return 0

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the values
    for i, (x, y, value) in enumerate(grid_values):
        if value == 0:
            break
        grid[x][y] = value

    # We need to calculate the maximum sum of going to the right & down only
    # with valid steps, so we build this flow network with source & sink
    #      [-----------增大路径] bottleneck [-------------]
    #  [           ] -        -        -          [           ]
    #  [	source	(bottleneck)	destination	(bottleneck)	]
    #  [		-        -          -        -          destination (sink)]
    #  -----------------------.total value of paths------------------------------------

    # Compute the flow in the network
    def augment(path):
        while path:
            v = path.pop()
            if v not in parent:
                parent[v] = path[-1]
                continue
            branch = graph[parent[v]][v]
            if branch['flow'] == branch['capacity']:
                continue
            path.append(v)
            dfs(branch['to'], min(branch['capacity'] - branch['flow'], delta))
            branch['flow'] += delta
            delta -= branch['capacity'] - branch['flow']

    graph = {}
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i == 0:
                if (i, j-1) not in graph:
                    graph[(i, j-1)] = {}
                graph[(i, j-1)][(i, j)] = {'value': 0, 'capacity': 1, 'to': (i, j), 'flow': 0}
                if (i+1, j-1) not in graph:
                    graph[(i+1, j-1)] = {}
                graph[(i+1, j-1)][(i, j)] = {'value': 0, 'capacity': 1, 'to': (i, j), 'flow': 0}
            elif j == 0:
                if (i-1, j) not in graph:
                    graph[(i-1, j)] = {}
                graph[(i-1, j)][(i, j)] = {'value': 0, 'capacity': 1, 'to': (i, j), 'flow': 0}
                if (i, j+1) not in graph:
                    graph[(i, j+1)] = {}
                graph[(i, j+1)][(i, j)] = {'value': 0, 'capacity': 1, 'to': (i, j), 'flow': 0}
            else:
                if (i-1, j) not in graph:
                    graph[(i-1, j)] = {}
                graph[(i-1, j)][(i, j)] = {'value': grid[i-1][j], 'capacity': 1, 'to': (i, j), 'flow': 0}
                if (i, j-1) not in graph:
                    graph[(i, j-1)] = {}
                graph[(i, j-1)][(i, j)] = {'value': grid[i][j-1], 'capacity': 1, 'to': (i, j), 'flow': 0}
                if (i+1, j) not in graph:
                    graph[(i+1, j)] = {}
                graph[(i+1, j)][(i, j)] = {'value': grid[i+1][j], 'capacity': 1, 'to': (i, j), 'flow': 0}
                if (i, j+1) not in graph:
                    graph[(i, j+1)] = {}
                graph[(i, j+1)][(i, j)] = {'value': grid[i][j+1], 'capacity': 1, 'to': (i, j), 'flow': 0}

    parent = {}
    dfs((N-1, N-1), float('inf'))

    max_flow = 0
    for i in range(N):
        for j in range(N):
            if i == N-1 and j == N-1:
                continue
            flow = 0
            if graph[(i, j)][(i+1, j)].get('to') != (i+1, j) or \
               graph[(i, j)][(i, j-1)].get('to') != (i, j-1) or \
               graph[(i, j)][(i-1, j)].get('to') != (i-1, j) or \
               graph[(i, j)][(i, j+1)].get('to') != (i, j+1):
                continue
            flow = min(graph[(i, j)][(i+1, j)]['capacity'], graph[(i, j)][(i, j-1)]['capacity'], \
                       graph[(i, j)][(i-1, j)]['capacity'], graph[(i, j)][(i, j+1)]['capacity'])
            max_flow += flow

    return max_flow
