    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = (grid_values[0][2], grid_values[0][2])
            elif i == 0:
                dp[i][j] = (dp[i][j - 1][0] + grid_values[i][2], max(dp[i][j - 1][1], dp[i][j - 1][0] + grid_values[i][2]))
            elif j == 0:
                dp[i][j] = (dp[i - 1][j][1] + grid_values[i][2], max(dp[i - 1][j][0], dp[i - 1][j][1] + grid_values[i][2]))
