from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if not grid_values or N == 0:
        return 0

    # Initialize the DP matrix
    dp = [[0 for _ in range(N)] for _ in range(N)]

    # Fill the DP matrix
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = grid_values[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + grid_values[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + grid_values[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid_values[i][j]

    # The maximum sum can be obtained from the bottom-right corner
    max_value = dp[N-1][N-1]

    # Generate all possible paths
    paths = []
    def backtrack(x, y, slate):
        if x == N-1 and y == N-1:
            paths.append(slate.copy())
            return
        for x1, y1 in [(x-1, y), (x, y-1)]:
            if 0 <= x1 < N and 0 <= y1 < N and not slate:
                slate.append(grid_values[x1][y1])
                backtrack(x1, y1, slate)
                slate.pop()

    backtrack(0, 0, [])

    # Select the path with the maximum sum
    max_sum_of_paths = max(sum(p) for p in paths)

    return max_value
