def cantor_numbering(num: int) -> str:
    if num <= 0:
        raise ValueError("Input must be a positive integer.")

    i = 1
    while True:
        j = 1
        while True:
            if i * j == num:
                if i % 2 == 1:
                    denominator = 1 + i // 2
                    numerator = i * denomination + 1
                else:
                    numerator = 1 + i // 2
                    denominator = i * (denominator + 2) - 1
                return f"{numerator}/{denominator}"
            elif i * j > num:
                break
            j += 1
        i += 2
