def max_product(num_str: str, N: int, K: int) -> int:
    def factorial(n: int) -> int:
        if n == 0:
            return 1
        else:
            return n * factorial(n - 1)

    def max_substring_length(n: int) -> int:
        # Calculate the maximum length of a subsequence
        if n <= 1:
            return n
        else:
            max_length = 0
            for i in range(n):
                for j in range(i + 1, n):
                    subseq_length = j - i + 1
                    if subseq_length > max_length and factorial(max_length) <= factorial(subseq_length) // factorial(subseq_length - max_length):
                        max_length = subseq_length
            return max_length

    # Calculate the number of ways to choose k positions for multiplication signs
    total_ways = factorial(N - K) // factorial(K)

    # Find the maximum possible product
    max_product = 0
    for i in range(max_substring_length(N), 0, -1):
        # Select the maximum product substring
        product = 1
        start = 0
        maximum_length = i
        for end in range(start + maximum_length, N + 1, maximum_length):
            substring = num_str[start:end]
            product *= int(substring)
            if product <= total_ways:
                max_product = product
                break
            start += maximum_length

    return max_product
```

