def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13 or not isbn.replace('-', '').isdigit():
        raise ValueError("Invalid ISBN format. Please use the format 'x-xxx-xxxxx-x'")

    def calculate_isbn_checksum(isbn):
        total = 0
        for i, char in enumerate(isbn[:12]):
            if char.isdigit():
                total += int(char) * (13 - i)
            elif char.upper() == 'X' and i == 12:
                total += 10
        return total % 11

    calculated_checksum = calculate_isbn_checksum(isbn)
    last_char = isbn[12]
    if last_char.upper() == 'X':
        corrected_isbn = isbn[:12] + '0'
        corrected_checksum = calculate_isbn_checksum(corrected_isbn)
        if corrected_checksum == calculated_checksum:
            return corrected_isbn
    else:
