        weight_factors = [1, 3, 1, 3, 1, 3, 1, 3]
        checksum = sum(digit * factor for digit, factor in zip(digits, weight_factors))
        return checksum % 11 == 0

    # Validate and correct the ISBN number
    if not isbn or not isbn.replace('-', '').isalnum() or len(isbn) != 13 or not isbn_checksum(isbn):
        return isbn  # Return the original ISBN if it's invalid

    # Generate the corrected ISBN number if checksum is incorrect
    if isbn_checksum(isbn):
        return isbn
    else:
        correction = 11 - (isbn[-1:].isdigit() and int(isbn[-1]) * 2 % 11 or 10)
        if correction == 10:
