def count_passing_ways(n: int, m: int) -> int:
    # Base case: If there are no students, there's only one way to pass the ball
    if n == 0:
        return 0
    # Base case: If there's only one student, there are no ways to pass the ball
    if n == 1:
        return 1

    # Initialize the DP table
    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the first row and column based on base cases
    dp[0][0] = 1  # There's only one way to have no passes
    for j in range(1, m + 1):
        dp[0][j] = 0  # No way to have a pass with only one student
    for i in range(1, n):
        dp[i][0] = 0  # No way to have a pass with no passes

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = (dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]) % (10**9 + 7)

    return dp[n - 1][m]
