    if beads[-1] != beads[0]:
        beads.append(beads[0])
    n = len(beads)

    # Create a DP table where dp[i][j] represents the maximum energy releasing beads i to j
    dp = [[0] * n for _ in range(n + 1)]
    for i in range(n):
        dp[i][i] = beads[i]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            # Update dp[i][j] to include all possible overlapping subproblems
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] * dp[k + 1][j])

