        if i == j:
            return beads[i]
        if dp[i][j] != -1:
            return dp[i][j]
        temp = -float('inf')
        for k in range(i, j):
            temp = max(temp, recursive_energy(i, k) + recursive_energy(k+1, j) * beads[i] * beads[j])
        dp[i][j] = temp
        return temp

    return recursive_energy(0, n-1)
