def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")

    quotient = y0 // x0
    if quotient == 1:
        return 2  # A pair (a, b) where a = b is always coprime, and there's one more (x0, x0) pair

    coprime_count = 0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                coprime_count += 2
    return coprime_count
