def preorder_traversal(inorder: str, postorder: str) -> str:
    def helper(postorder_index, start, end):
        if start == end:
            return [inorder[start]]
        root = postorder[postorder_index]
        index = inorder.find(root)
        left_subtree_size = index - start
        return [root] + helper(postorder_index - 1 - left_subtree_size, start, index - 1) + helper(postorder_index - 1, index + 1, end)

    n = len(postorder)
    return ''.join(helper(n - 1, 0, n - 1))
```

