def generate_numbers(n: int, rules: List[tuple]) -> int:
    def bfs(visited, queue, target):
        if target in visited:
            return 0
        visited.add(target)
        queue.append(target)
        count = 1
        while queue:
            current = queue.pop(0)
            for rule in rules:
                if current in rule:
                    transformed = current - (rule[1] - rule[0]) if rule[0] > rule[1] else current + (rule[1] - rule[0])
                    if transformed == target:
                        count += 1
                    elif transformed not in visited and transformed.isdigit():
                        visited.add(transformed)
                        queue.append(transformed)
        return count

    visited = set()
    queue = [n]
    return bfs(visited, queue, n)
