def generate_numbers(n, rules) -> int:
    if n < 0:
        raise ValueError("Input number must be non-negative")

    # Convert number to a set of digits
    digits = set(int(digit) for digit in str(n))

    # Queue to store elements to process
    queue = deque([digit] for digit in digits)
    seen = {digit for digit in digits}
    count = 0

    while queue:
        current = queue.popleft()

        # Apply each rule to the current digit
        for prev, next in rules:
            if prev == current:
                next_digit = str(next)
                if int(next_digit) not in seen:
                    seen.add(int(next_digit))
                    if int(next_digit) not in digits:
                        count += 1
                    queue.append(int(next_digit))

    return count
