def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or M > len(herbs):
        raise ValueError("Invalid input provided")

    @cache
    def dp(t, remaining_herbs):
        if t <= 0 or len(remaining_herbs) == 0:
            return 0

        time_cost, value = herbs[len(remaining_herbs) - 1]

        # If it's possible to pick the current herb, pick it and subtract the time cost from the remaining time
        pick = value + dp(t - time_cost, remaining_herbs[:-1])

        # If not, skip the current herb and continue with the remaining herbs
        skip = dp(t, remaining_herbs[:-1])

        return max(pick, skip)

    return dp(T, herbs)
