    # Initialize the dynamic programming table
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Populate the dynamic programming table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the capacity and the maximum occupied space
    min_remaining_space = V - dp[n][V]
    return min_remaining_space
