def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7

    @lru_cache(maxsize=None)
    def count_ways(current_type, remaining_pots):
        if current_type == n: 
            return 1 if remaining_pots == 0 else 0
        ans = 0
        for _, max_pots in enumerate(a):
            if remaining_pots < max_pots: 
                continue
            ans += count_ways(current_type + 1, remaining_pots - max_pots)
        return ans % MOD

    return count_ways(0, m)
