def next_permutation(perm: list) -> bool:
    # Iterate from the second last element to the first element
    for i in range(len(perm) - 2, -1, -1):
        # Check if the current element is smaller than the element before it
        if perm[i] < perm[i + 1]:
            # Find the smallest element in the sublist to the right of the current element that is larger than it
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap the current element with the smallest element found
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the sublist to the right of the current element
                    perm[i + 1:] = reversed(perm[i + 1:])
                    return True
    return False
```

