def next_permutation(perm: list) -> bool:
    n = len(perm)

    # Find the first number from the end that is smaller than the number following it
    for i in range(n-2, -1, -1):
        if perm[i] < perm[i+1]:
            break

    # If no such number is found, return False (no next permutation possible)
    if i == -1:
        return False

    # Find the smallest number that is larger and comes after the originally found number
    for j in range(n-1, i, -1):
        if perm[j] > perm[i]:
            break

    # Swap the found numbers
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of numbers after the original first smaller number
    perm[i+1:] = perm[i+1:][::-1]

    return True
```

