def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be a positive integer.")

    # Base case: calculate the number of moves for a single pair of discs
    def single_disc_moves(num_pairs):
        return 2 * num_pairs

    # Base case: calculate the number of moves for two pairs of discs
    def two_disc_moves(num_pairs):
        return 4 * num_pairs

    # Base case: calculate the number of moves for three pairs of discs
    def three_disc_moves(num_pairs):
        return 8 * num_pairs

    # Recursively calculate the total number of moves for n pairs of discs
    if n == 1:
        return single_disc_moves(n)
    elif n == 2:
        return two_disc_moves(n)
    elif n == 3:
        return three_disc_moves(n)
    else:
        # For all other values of n, use a known recursive relation
        return (2*n - 1) * (2*n) // 2
```

