def total_smoked_cigarettes(n, k):
    if not isinstance(n, int) or not isinstance(k, int):
        raise ValueError("Both n and k must be integers.")
    if n <= 0:
        raise ValueError("Initial number of cigarettes (n) must be a positive integer.")
    if k <= 0:
        raise ValueError("Number of cigarette butts to exchange for one new cigarette (k) must be a positive integer.")

    total_smoked = 0
    while n >= k:
        total_smoked += 1
        n -= k
    return total_smoked + n
